import{_ as o,o as a,c as s,a2 as r}from"./chunks/framework.Ck6QqhZl.js";const f=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"docs/glossary.md","filePath":"docs/glossary.md"}'),t={name:"docs/glossary.md"};function d(n,e,c,i,l,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Short definitions for the terms used across Soundef docs. Deep detail lives in the <a href="./spec">Spec</a>.</p><p><strong>Soundef</strong>: the declarative format (<code>.soundef</code>) <em>and</em> the project. A <code>.soundef</code> file describes the <em>behavior</em> of a game sound when triggered, not a fixed audio file.</p><p><strong>Forge</strong>: the desktop app that edits, previews, bakes, and shares <code>.soundef</code> files. See <a href="./getting-started">Getting Started</a>.</p><p><strong><code>.soundef</code> file</strong>: a YAML 1.2 document (JSON is valid too) with <code>name</code>, <code>version: 0</code>, and <code>layers</code>. See <a href="./spec">Spec</a>.</p><p><strong>Layer</strong>: one lane of a sound, under <code>layers.&lt;name&gt;</code>. Each layer picks and places one file per trigger. Layer order is the timeline display order. See <a href="./spec#layers-layers-name">Layers</a>.</p><p><strong>Source</strong>: a file path in a layer&#39;s <code>sources</code> list, relative to the project <code>sounds/</code> folder (bare, <code>sounds/</code>-only, no <code>../</code> or <code>/absolute</code>). Basename globs (<code>*</code>, <code>?</code>) are allowed. See <a href="./spec#sources">Sources</a>.</p><p><strong>Selection</strong>: how a layer chooses among its <code>sources</code> per trigger: <code>random</code> (uniform) or <code>sequence</code> (round-robin). <code>avoidRepeat</code> prevents recent repeats in random mode. See <a href="./spec#selection">Selection</a>.</p><p><strong>Probability</strong>: the chance a layer plays at all (<code>0..1</code>), rolled per trigger, per layer. A failed roll marks the layer <code>skipped</code>.</p><p><strong>offset</strong>: time from the event trigger to a layer&#39;s start, in milliseconds. Distinct from a DSP <code>delay</code> line. See the <a href="./faq">FAQ</a>.</p><p><strong>gain</strong>: a layer&#39;s level in decibels. <code>0dB</code> = unity; negative = quieter. Converted to linear as <code>10^(dB/20)</code> at playback.</p><p><strong>pitch</strong>: a layer&#39;s pitch shift in semitones. <code>12st</code> = one octave. Converted to a rate as <code>2^(st/12)</code>; source duration scales with it.</p><p><strong>Value forms</strong>: <code>offset</code>/<code>gain</code>/<code>pitch</code> accept a scalar with unit (<code>&quot;-2dB&quot;</code>), a bare number (implicit unit, warns), or a <code>randomRange: [min, max]</code> lerped per trigger. See <a href="./spec#value-forms">Value forms</a>.</p><p><strong>randomRange</strong>: <code>{ randomRange: [min, max] }</code>. A uniform pick between two bounds (same unit both ends) chosen per trigger with the layer&#39;s RNG.</p><p><strong>seed</strong>: a <code>string | number</code> that drives all randomness. Same definition + same seed → same result. See <a href="./spec#determinism">Determinism</a>.</p><p><strong>Determinism</strong>: <code>definition + seed → the same PlaybackPlan</code>, always, on every platform. Enables reproducible variation.</p><p><strong>Isolated RNG</strong>: each layer uses its own random stream seeded <code>seed + &quot;#&quot; + layerName</code>, so changing one layer never shifts another&#39;s rolls. Effects use <code>#reverb</code>/<code>#delay</code>/<code>#limiter</code> streams. See <a href="./integration#determinism-contract">Integration</a>.</p><p><strong>PlaybackPlan</strong>: the resolved plan for a <code>seed</code>: a JSON object with <code>name</code>, <code>seed</code>, <code>layers</code> (concrete <code>source</code> + <code>offset</code> ms + <code>gain</code> dB + <code>pitch</code> st), and optional <code>effects</code>. See <a href="./integration#the-playbackplan-json-shape">Integration: The PlaybackPlan</a>.</p><p><strong>ResolvedLayer</strong>: one entry in a plan&#39;s <code>layers</code>: <code>source</code>, <code>offset</code> (ms), <code>gain</code> (dB), <code>pitch</code> (st), and optional <code>skipped</code>.</p><p><strong>skipped / ghost</strong>: a layer whose probability roll failed. Kept in the plan (<code>skipped: true</code>) so the timeline can draw it as a dashed ghost; playback and bake ignore it.</p><p><strong>Effects</strong>: an optional, Forge-only <code>effects</code> block (<code>reverb</code>, <code>delay</code>, <code>limiter</code>). Baked render includes it; a live runtime may skip it. Users may implement it. See <a href="./spec#effects">Effects</a>.</p><p><strong>forge-only</strong>: a warning for <code>effects.*</code> keys: ignored live, baked only. Unknown keys inside <code>effects</code> are allowed and surface as this warning, not an error.</p><p><strong>Bake</strong>: render a <code>.soundef</code> + seed to a plain <code>wav</code> in <code>baked/</code>. A baked file needs no runtime: useful for A/B against live, or shipping without a Soundef runtime. See <a href="./getting-started#bake--download--share">Bake</a>.</p><p><strong>Pack</strong>: a <code>.zip</code> (<code>Export Pack</code> / <code>Import Pack</code>) bundling <code>soundefs/*</code>, <code>sounds/**</code>, an optional preview, and a <code>manifest.json</code> (<code>version: 0</code>) for sharing a project.</p><p><strong>Diagnostic</strong>: a <code>{ severity, message, code, range }</code> note from <code>parse</code>/<code>resolve</code>. <code>error</code> blocks the plan; <code>warning</code> still plays. See <a href="./spec#diagnostics">Diagnostics</a>.</p><p><strong>Runtime</strong>: an engine-side implementation that plays a <code>PlaybackPlan</code> (Godot/Unity/Unreal/Bevy/web). Optional: Forge can bake to <code>wav</code> instead. See <a href="./integration">Integration</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./spec">Spec</a>: full file reference. Schema at <a href="/soundef-site/schemas/soundef.v0.json">/schemas/soundef.v0.json</a>.</li><li><a href="./integration">Integration</a>: how a runtime turns a <code>PlaybackPlan</code> into audio.</li></ul>',28)])])}const h=o(t,[["render",d]]);export{f as __pageData,h as default};
